WITH valid AS (SELECT *, CONCAT_WS('/', brand, product_name) AS brand_product_name_key, COALESCE(brand, 'N/A') AS brand_filled FROM products WHERE stock_qty BETWEEN 288 AND 362), enriched AS (SELECT src.id, src.product_name, src.brand, src.price, src.launch_date, src.tags, src.supplier_id, src.brand_filled, d.city, d.supplier_name, d.rating FROM valid src LEFT JOIN suppliers d ON src.supplier_id <=> d.id WHERE LOWER(TRIM(d.supplier_name)) = 'pacific wholesale'), valid_products AS (SELECT *, TRIM(brand) AS clean_brand, COALESCE(brand, 'OTHER') AS brand_clean FROM enriched WHERE launch_date >= DATE '2023-09-13' AND city IS NOT NULL), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY supplier_id ORDER BY price DESC NULLS LAST, id ASC) AS row_num FROM valid_products) ranked WHERE row_num = 1), with_dims AS (SELECT src.*, s.city AS supplier_city FROM latest src LEFT JOIN suppliers s ON src.supplier_id = s.id), with_windows AS (SELECT id, product_name, price, launch_date, tags, brand_filled, city, supplier_name, clean_brand, row_num, SUM(price) OVER (PARTITION BY city ORDER BY row_num ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_price, AVG(price) OVER (PARTITION BY YEAR(launch_date), supplier_city ORDER BY row_num ASC, id ASC ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS price_avg_5, CUME_DIST() OVER w_grp AS rating_cume_dist, AVG(rating) OVER (ORDER BY row_num ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS rating_avg_6, ROUND(price / SUM(price) OVER (PARTITION BY city), 4) AS price_share FROM with_dims WINDOW w_grp AS (PARTITION BY brand ORDER BY rating ASC NULLS LAST)) SELECT city, COUNT(*) FILTER (WHERE city = 'Singapore') AS singapore_rows, COUNT(*) AS event_count FROM with_windows GROUP BY city
